import torchvision.transforms as transforms
from PIL import Image as PILImage

def pil_loader(path):
    """Custom loader that tries multiple approaches."""
    try:
        with open(path, 'rb') as f:
            img = PILImage.open(f)
            img.load()
            return img.convert('RGB')
    except Exception as e:
        # Try without explicit file open
        try:
            return PILImage.open(path).convert('RGB')
        except:
            raise e

class SafeImageFolder(ImageFolder):
    def __init__(self, root, transform=None, target_transform=None):
        # Override the default loader with our custom one
        super().__init__(root, loader=pil_loader, transform=transform, target_transform=target_transform)

transformations = transforms.Compose([transforms.Resize((256, 256)), transforms.ToTensor()])

dataset = SafeImageFolder(directory_path, transform=transformations)"}

